using System;using UnityEngine;using LighFight.Runtime;using SourceContact;using LazySourceContact;using SourceResponse;
namespace SourceContactReview {
 // Certificate implementations must enclose ALL actual Animator/native-overlay motion in the interval.
 // No implementation based only on endpoints, dense samples, or matrix lerps is supplied by this packet.
 public interface IAnimatorIntervalCertificate {
  PhaseInterval Evaluate(AnimatorPhaseCollisionBridge bridge,double from,double to,out double lastSafePhase,out ImpactAnatomy anatomy);
 }
 public struct SampledPhaseTransition {public PairInspection Start,End;public bool FoundContact,IntervalUnqualified;public double LastSampledOutside,FirstSampledContact;public PairEvidence Evidence;}
 public sealed class AnimatorPhaseCollisionBridge:ISourcePhaseOracle {
  readonly SourceSurfaceReviewAdapter attacker,target;readonly Animator animator;readonly string state;readonly IContactPoseHook[] hooks;readonly CandidatePairInspection pair=new CandidatePairInspection();readonly CandidateFootGrounding grounding;readonly NativeFingerPoseDriver fingers;readonly Transform rootA,rootB;readonly Vector3 positionA,positionB;readonly Quaternion rotationA,rotationB;
  public IAnimatorIntervalCertificate Certificate;public PairInspection LastObservation{get;private set;}public PairEvidence LastEvidence{get;private set;}public double DisplayedPhase{get;private set;}public AttackResponse Response{get;private set;}public event Action<AttackDecision> QualifiedImpact;
  public AnimatorPhaseCollisionBridge(SourceSurfaceReviewAdapter a,SourceSurfaceReviewAdapter b,Animator sourceAnimator,string stateName){if(!a||!b||!a.IsWarm||!b.IsWarm||!sourceAnimator)throw new ArgumentException("Warm actual actors first");attacker=a;target=b;animator=sourceAnimator;state=stateName;if(!animator.HasState(0,Animator.StringToHash("Base Layer."+state)))throw new ArgumentException("Missing approved source state");rootA=a.GetComponentInParent<FighterView>().transform;rootB=b.GetComponentInParent<FighterView>().transform;positionA=rootA.position;positionB=rootB.position;rotationA=rootA.rotation;rotationB=rootB.rotation;var components=rootA.GetComponents<MonoBehaviour>();int n=0;foreach(var component in components)if(component is IContactPoseHook)n++;hooks=new IContactPoseHook[n];n=0;foreach(var component in components)if(component is IContactPoseHook)hooks[n++]=(IContactPoseHook)component;grounding=rootA.GetComponent<CandidateFootGrounding>();fingers=rootA.GetComponent<NativeFingerPoseDriver>();Response=new AttackResponse();}
  void CheckRoots(){if(rootA.position!=positionA||rootB.position!=positionB||Quaternion.Angle(rootA.rotation,rotationA)>.0001f||Quaternion.Angle(rootB.rotation,rotationB)>.0001f)throw new InvalidOperationException("Constant-root phase bridge invalidated by root/facing motion");}
  // REVIEW-owned actors only. Production sampling must be suspended while this bridge owns Animator.
  // Uses actual Animator and existing source overlay/finger/grounding hooks, never writes individual bones.
  public PairInspection Sample(double phase,int work=100000){CheckRoots();if(double.IsNaN(phase)||double.IsInfinity(phase)||phase<0||phase>1)throw new ArgumentOutOfRangeException();foreach(var hook in hooks)hook.InvalidateContactPose();if(grounding)grounding.ResetForSample();animator.speed=0;animator.applyRootMotion=false;animator.Play("Base Layer."+state,0,(float)phase);animator.Update(0);if(fingers)fingers.ApplyContactPose();foreach(var hook in hooks)hook.ApplyContactPose();if(grounding)grounding.ApplyForReview();attacker.CaptureSampledPose();target.CaptureSampledPose();var budget=new WorkBudget(work);PairEvidence evidence;LastObservation=pair.Inspect(attacker.Surface,target.Surface,attacker.MainTopology,target.MainTopology,ref budget,out evidence);LastEvidence=evidence;DisplayedPhase=phase;return LastObservation;}
  // Boundary localization for a runnable audit. This is explicitly NOT continuous clearance.
  // Unseen contact/retraction between samples remains unresolved even when all samples are outside.
  public SampledPhaseTransition LocalizeSampledContact(double from,double to,int subdivisions=32,int bisections=12){if(subdivisions<1||subdivisions>1024||bisections<0||bisections>32||to<from)throw new ArgumentException();var result=new SampledPhaseTransition{IntervalUnqualified=true,LastSampledOutside=from,FirstSampledContact=from};result.Start=Sample(from);result.End=result.Start;if(result.Start!=PairInspection.ProvisionalOutsideBoth)return result;
   double low=from;for(int i=1;i<=subdivisions;i++){double phase=from+(to-from)*i/subdivisions;result.End=Sample(phase);if(result.End==PairInspection.Indeterminate)return result;if(result.End!=PairInspection.ProvisionalOutsideBoth){double high=phase;for(int n=0;n<bisections;n++){double mid=(low+high)*.5;var observed=Sample(mid);if(observed==PairInspection.Indeterminate)return result;if(observed==PairInspection.ProvisionalOutsideBoth)low=mid;else high=mid;}result.FoundContact=true;result.LastSampledOutside=low;result.FirstSampledContact=high;Sample(high);result.Evidence=LastEvidence;Sample(low);return result;}low=phase;result.LastSampledOutside=low;}return result;
  }
  public PhaseInterval Inspect(double from,double to,out double lastSafePhase,out ImpactAnatomy anatomy){CheckRoots();lastSafePhase=from;anatomy=ImpactAnatomy.Other;if(Certificate==null)return PhaseInterval.Indeterminate;return Certificate.Evaluate(this,from,to,out lastSafePhase,out anatomy);}
  public AttackDecision Advance(double requestedPhase,double seconds,bool legalCombatWindow){var decision=Response.Tick(requestedPhase,seconds,legalCombatWindow,this);Sample(decision.Phase);if(decision.EmitImpact)QualifiedImpact?.Invoke(decision);return decision;}
 }
}
